-- Historique 2026 importe de Leaguepedia (https://lol.fandom.com, CC BY-SA 3.0) par
-- import/import_leaguepedia.py : NE PAS EDITER A LA MAIN, regenerer le fichier.
-- Structure des tournois (phases, poules, brackets relies) SANS les scores : les
-- resultats se saisissent dans l'appli, les playoffs avancent au fil des scores.

CREATE TEMP TABLE lp_team (lp_name TEXT PRIMARY KEY, team_id BIGINT NOT NULL);
CREATE TEMP TABLE lp_match (k TEXT PRIMARY KEY, match_id BIGINT NOT NULL);

-- Equipe actuelle (apres renommages) : existante de meme nom, ou de meme code si elle
-- existe encore aujourd'hui ; sinon creee (code rendu unique si deja pris).
-- En SQL simple, sans PL/pgSQL (plpgsql.dll peut etre bloquee sur un poste Windows).
WITH created AS (INSERT INTO team (code, name, region) SELECT (SELECT c FROM (SELECT 'AL' AS c, 1 AS n UNION ALL SELECT 'AL' || n, n FROM generate_series(2, 99) n) x WHERE NOT EXISTS (SELECT 1 FROM team WHERE code = x.c) ORDER BY n LIMIT 1), 'Anyone''s Legend', 'China' WHERE NOT EXISTS (SELECT 1 FROM lp_team WHERE lp_name = 'Anyone''s Legend') RETURNING id) INSERT INTO lp_team SELECT 'Anyone''s Legend', id FROM created;
